        $pointSql="SELECT pi.fiche_number,pi.amount,pi.beneficiary,pi.designation,pi.chantier_code,pi.chantier_title,pi.next_disbursement_date,p.id point_id,p.version_no,p.status point_status,COALESCE(f.decaisse,0) paid,f.date_decaisse,CASE WHEN p.id=:current THEN 'current_point' ELSE 'other_point' END source_type FROM daily_disbursement_points p JOIN daily_disbursement_point_items pi ON pi.point_id=p.id LEFT JOIN fiche_decaissement f ON CONVERT(f.num_fiche USING utf8mb4) COLLATE utf8mb4_general_ci=CONVERT(pi.fiche_number USING utf8mb4) COLLATE utf8mb4_general_ci WHERE p.point_date=:day";
