        $manualSql="SELECT f.num_fiche fiche_number,f.montant_fiche amount,f.beficiaire_fiche beneficiary,f.designation_fiche designation,c.code chantier_code,c.titre chantier_title,NULL next_disbursement_date,NULL point_id,NULL version_no,NULL point_status,1 paid,f.date_decaisse,'manual' source_type FROM fiche_decaissement f LEFT JOIN chantier_banamur c ON c.id=f.chantier_id WHERE f.decaisse=1 AND DATE(f.date_decaisse)=:paid_day AND NOT EXISTS(SELECT 1 FROM daily_disbursement_point_items dpi JOIN daily_disbursement_points dp ON dp.id=dpi.point_id WHERE CONVERT(dpi.fiche_number USING utf8mb4) COLLATE utf8mb4_general_ci=CONVERT(f.num_fiche USING utf8mb4) COLLATE utf8mb4_general_ci AND dp.point_date=:point_day)";
        $s=$this->pdo->prepare($manualSql);$s->execute(['paid_day'=>$date,'point_day'=>$date]);$items=array_merge($items,$s->fetchAll(PDO::FETCH_ASSOC)?:[]);usort($items,static fn(array $a,array $b):int=>[(string)($a['date_decaisse']??''),(int)($a['point_id']??PHP_INT_MAX),(string)$a['fiche_number']]<=>[(string)($b['date_decaisse']??''),(int)($b['point_id']??PHP_INT_MAX),(string)$b['fiche_number']]);
        $requested=0.0;$paid=0.0;$toPay=0.0;$pointRequested=0.0;$pointPaid=0.0;$pointToPay=0.0;foreach($items as &$item){$amount=(float)$item['amount'];$isPaid=(int)$item['paid']===1;$item['payment_status']=$isPaid?'paid':'to_pay';$item['source_label']=$item['source_type']==='manual'?'Décaissement manuel':('Point V'.(int)$item['version_no'].($item['source_type']==='current_point'?' · point consulté':''));$requested+=$amount;if($isPaid)$paid+=$amount;else$toPay+=$amount;if($item['source_type']==='current_point'){$pointRequested+=$amount;if($isPaid)$pointPaid+=$amount;else$pointToPay+=$amount;}}unset($item);return['items'=>$items,'totals'=>['requested'=>$requested,'paid'=>$paid,'to_pay'=>$toPay],'point_totals'=>['requested'=>$pointRequested,'paid'=>$pointPaid,'to_pay'=>$pointToPay]];
    }
