        foreach($items as &$row){$num=(string)$row['num_fiche'];$plan=(array)($plans[$num]??[]);$original=(float)$row['montant_fiche'];$amount=(float)($plan['amount']??$original);$next=trim((string)($plan['next_date']??''));if($amount<=0||$amount>$original)throw new RuntimeException('Montant à décaisser invalide pour '.$num.'.');if($amount<$original&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$next)||$next<=$today))throw new RuntimeException('Indiquez une prochaine date future pour le reliquat de '.$num.'.');$row['point_amount']=$amount;$row['next_disbursement_date']=$amount<$original?$next:null;}unset($row);try{$this->pdo->exec('ALTER TABLE daily_disbursement_point_items ADD COLUMN next_disbursement_date DATE NULL AFTER amount');}catch(Throwable $e){}
