    }
    public function canView(array $point,int $userId,bool $financeOrAdmin):bool{if($financeOrAdmin)return true;$s=$this->pdo->prepare('SELECT 1 FROM daily_disbursement_point_authorizations WHERE point_id=:p AND user_id=:u LIMIT 1');$s->execute(['p'=>$point['id'],'u'=>$userId]);return(bool)$s->fetchColumn();}
    public function authorize(int $pointId,int $userId,string $role,int $grantedBy,?int $delegatorId=null):void{$role=in_array($role,['signer','dg'],true)?$role:'signer';$entitledUser=$delegatorId?:$userId;$check=$this->pdo->prepare('SELECT acces_signataire_point_jour FROM user_devis_banamur WHERE id=:id AND active=1 LIMIT 1');$check->execute(['id'=>$entitledUser]);if(!(bool)$check->fetchColumn())throw new RuntimeException($delegatorId?'Le donneur de procuration ne possède pas le droit « Signataire du point du jour ».':'Cet utilisateur ne possède pas le droit « Signataire du point du jour ».');$s=$this->pdo->prepare('INSERT INTO daily_disbursement_point_authorizations(point_id,user_id,role_code,delegator_user_id,granted_by_user_id) VALUES(:p,:u,:r,:d,:g) ON DUPLICATE KEY UPDATE role_code=VALUES(role_code),delegator_user_id=VALUES(delegator_user_id),granted_by_user_id=VALUES(granted_by_user_id),revoked_at=NULL');$s->execute(['p'=>$pointId,'u'=>$userId,'r'=>$role,'d'=>$delegatorId,'g'=>$grantedBy]);$meta=$this->pdo->prepare('SELECT version_no,point_date FROM daily_disbursement_points WHERE id=:id');$meta->execute(['id'=>$pointId]);$pointMeta=$meta->fetch(PDO::FETCH_ASSOC)?:[];$title='Point #'.$pointId.' · V'.(int)($pointMeta['version_no']??0).' à signer';$message='Vous êtes désigné '.($delegatorId?'mandataire en PO':'signataire').' pour le point #'.$pointId.' du '.(!empty($pointMeta['point_date'])?date('d/m/Y',strtotime((string)$pointMeta['point_date'])):'jour').'.';$this->notify($userId,$title,$message,'/decaissement/point_decaissement_jour.php?id='.$pointId);}
    public function delegate(int $pointId,int $delegatorId,int $delegateId,int $grantedBy):void
    {
        if($delegateId<=0||$delegateId===$delegatorId)throw new RuntimeException('Sélectionnez une autre personne comme mandataire.');
        $s=$this->pdo->prepare('SELECT role_code FROM daily_disbursement_point_authorizations WHERE point_id=:p AND user_id=:u AND revoked_at IS NULL LIMIT 1');$s->execute(['p'=>$pointId,'u'=>$delegatorId]);$role=(string)$s->fetchColumn();if($role==='')throw new RuntimeException('Vous n’êtes pas désigné pour signer ce point.');
