        $this->pdo->prepare('UPDATE daily_disbursement_point_authorizations SET revoked_at=NOW() WHERE point_id=:p AND user_id=:u')->execute(['p'=>$pointId,'u'=>$delegatorId]);
    }
    public function provisionConfiguredSigners(int $pointId,int $grantedBy):void
    {
        $this->pdo->prepare("UPDATE daily_disbursement_point_authorizations SET revoked_at=COALESCE(revoked_at,NOW()) WHERE point_id=:p AND role_code<>'dg'")->execute(['p'=>$pointId]);
        $check=$this->pdo->prepare("SELECT COUNT(*) FROM daily_disbursement_point_authorizations WHERE point_id=:p AND role_code='dg' AND revoked_at IS NULL");$check->execute(['p'=>$pointId]);if((int)$check->fetchColumn()>0)return;
        $columns=$this->pdo->query('SHOW COLUMNS FROM user_devis_banamur')->fetchAll(PDO::FETCH_COLUMN,0)?:[];
        $direction=in_array('acces_direction',$columns,true)?'COALESCE(acces_direction,0)':'0';
        $boss=$this->syncRhDirectorSignatureRight();if(!$boss)$boss=$this->pdo->query("SELECT id FROM user_devis_banamur WHERE active=1 AND acces_signataire_point_jour=1 ORDER BY ($direction=1) DESC,id ASC LIMIT 1")->fetchColumn();
