        $this->authorize($pointId,(int)$boss,'dg',$grantedBy);
    }
    public function sign(int $pointId,int $userId,string $userName,string $signaturePath=''):array
    {FinancialWorkflowProgress::step('Vérification et enregistrement de la signature du point.');
        if (trim($signaturePath)==='') throw new RuntimeException('La signature du DG est obligatoire.');
        $this->pdo->beginTransaction();
        try {
        $lock=$this->pdo->prepare('SELECT id FROM daily_disbursement_points WHERE id=? FOR UPDATE');$lock->execute([$pointId]);
        $point=$this->find($pointId);if(!$point)throw new RuntimeException('Point introuvable.');if(!empty($point['export_allowed'])){$this->pdo->commit();return$point;}if((string)$point['status']!=='stopped'||empty($point['items']))throw new RuntimeException('Ce point ne peut pas être signé.');
        $s=$this->pdo->prepare('SELECT role_code,delegator_user_id FROM daily_disbursement_point_authorizations WHERE point_id=:p AND user_id=:u AND role_code=\'dg\' AND revoked_at IS NULL LIMIT 1');$s->execute(['p'=>$pointId,'u'=>$userId]);$auth=$s->fetch(PDO::FETCH_ASSOC);if(!$auth)throw new RuntimeException('Vous n’êtes pas autorisé à signer ce point.');
