        $insert->execute(['p'=>$pointId,'u'=>$userId,'name'=>$userName,'role'=>'dg','delegator'=>$auth['delegator_user_id'],'path'=>$signaturePath,'ip'=>$_SERVER['REMOTE_ADDR']??'']);
        $this->pdo->prepare("UPDATE daily_disbursement_points SET status='certified',certified_at=NOW() WHERE id=:id")->execute(['id'=>$pointId]);
        $this->pdo->commit();
        } catch (Throwable $e) { if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e; }
        $paymentKey='';try{require_once __DIR__.'/DailyPointExternalSignatureService.php';$externalSignature=new DailyPointExternalSignatureService($this->pdo);$externalSignature->revokePointLinks($pointId);$paymentKey=$externalSignature->issuePaymentKey($pointId);}catch(Throwable $e){}
        $this->notify((int)$point['stopped_by_user_id'],'Point signé — Bon pour paiement #'.$pointId,'Le Directeur Général a signé le point. Les fiches de ce point peuvent maintenant être décaissées manuellement.','/decaissement/point_decaissement_jour.php?id='.$pointId);
        $result=$this->find($pointId)??[];if($paymentKey!==''){$result['_payment_key']=$paymentKey;if(session_status()===PHP_SESSION_ACTIVE)$_SESSION['daily_point_new_payment_key'][$pointId]=$paymentKey;}return$result;
    }
    public function disburse(int $pointId,string $userName,int $userId=0,string $signaturePath=''):array
    {
        $point=$this->find($pointId);$numbers=array_map(static fn(array $item):string=>(string)$item['fiche_number'],(array)($point['items']??[]));return$this->disburseSelection($pointId,$numbers,$userName,$userId,$signaturePath,'autre','','');
    }
    public function disburseSelection(int $pointId,array $numbers,string $userName,int $userId,string $signaturePath,string $paymentMode,string $paymentReference='',string $proofPath=''):array
    {
        $lockName = 'finea_point_payment_'.$pointId;
        $lock = $this->pdo->prepare('SELECT GET_LOCK(?,5)');
        $lock->execute([$lockName]);
        if ((int)$lock->fetchColumn() !== 1) throw new RuntimeException('Un paiement de ce point est déjà en cours. Réessayez.');
        try { return $this->executeDisburseSelection($pointId,$numbers,$userName,$userId,$signaturePath,$paymentMode,$paymentReference,$proofPath); }
        finally { $release=$this->pdo->prepare('SELECT RELEASE_LOCK(?)'); $release->execute([$lockName]); }
    }
    private function executeDisburseSelection(int $pointId,array $numbers,string $userName,int $userId,string $signaturePath,string $paymentMode,string $paymentReference='',string $proofPath=''):array
    {FinancialWorkflowProgress::step('Contrôle des autorisations et préparation du paiement du point.');
        $sessionPoint=(int)($_SESSION['daily_point_payment_access']['point_id']??0);if($sessionPoint>0&&$sessionPoint!==$pointId)throw new RuntimeException('La clé saisie n’autorise pas le décaissement de ce point.');
        $point=$this->find($pointId);if(!$point)throw new RuntimeException('Point introuvable.');if((string)$point['status']==='paid')return$point;if((string)$point['status']!=='certified'||empty($point['certified_at']))throw new RuntimeException('La signature du Directeur Général est requise avant le décaissement.');if($userId<=0||$signaturePath==='')throw new RuntimeException('L’identité et la signature de l’agent payeur sont obligatoires.');$modes=['virement','cheque','especes','mobile_money','carte','autre'];if(!in_array($paymentMode,$modes,true))throw new RuntimeException('Sélectionnez un mode de paiement valide.');$first=$this->pdo->query("SELECT id FROM daily_disbursement_points WHERE status IN ('stopped','certified') ORDER BY point_date,version_no,id LIMIT 1")->fetchColumn();if((int)$first!==$pointId)throw new RuntimeException('Le point #'.(int)$first.' doit être traité avant le point #'.$pointId.'.');$numbers=array_values(array_unique(array_filter(array_map('trim',$numbers))));if(!$numbers)throw new RuntimeException('Sélectionnez au moins une fiche à décaisser.');$allowed=[];foreach((array)$point['items'] as $item)$allowed[(string)$item['fiche_number']]=$item;foreach($numbers as $number)if(!isset($allowed[$number]))throw new RuntimeException('La fiche '.$number.' n’appartient pas à ce point.');$processed=$this->executePointDisbursements($point,$userName,$numbers);if(!$processed['numbers'])throw new RuntimeException($processed['errors'] ? implode("\n", $processed['errors']) : 'Les fiches sélectionnées sont déjà décaissées.');$insert=$this->pdo->prepare('INSERT INTO daily_disbursement_point_payments(point_id,user_id,payer_name,signature_path,payment_mode,payment_reference,proof_path,total_amount,item_count,paid_at) VALUES(:point,:user,:name,:signature,:mode,:reference,:proof,:total,:count,NOW())');$insert->execute(['point'=>$pointId,'user'=>$userId,'name'=>$userName,'signature'=>$signaturePath,'mode'=>$paymentMode,'reference'=>trim($paymentReference),'proof'=>trim($proofPath),'total'=>$processed['total'],'count'=>count($processed['numbers'])]);$batchId=(int)$this->pdo->lastInsertId();$itemInsert=$this->pdo->prepare('INSERT INTO daily_disbursement_point_payment_items(payment_id,point_item_id,fiche_number,amount) VALUES(:payment,:item,:fiche,:amount)');foreach($processed['numbers'] as $number){$item=$allowed[$number];$itemInsert->execute(['payment'=>$batchId,'item'=>(int)$item['id'],'fiche'=>$number,'amount'=>(float)$item['amount']]);}$updated=$this->find($pointId)??$point;if((float)($updated['point_totals']['to_pay']??0)<=0)$this->pdo->prepare("UPDATE daily_disbursement_points SET status='paid',paid_at=NOW(),paid_by_user_id=:uid,paid_by_name=:name,paid_by_signature_path=:signature WHERE id=:id")->execute(['id'=>$pointId,'uid'=>$userId,'name'=>$userName,'signature'=>$signaturePath]);if($processed['errors'])throw new RuntimeException("Décaissement du point incomplet ; les paiements réussis sont enregistrés :\n".implode("\n",$processed['errors']));return$this->find($pointId)??$updated;
    }
    public function exportAllowed(array $point):bool{return in_array((string)($point['status']??''),['certified','paid'],true)&&!empty($point['certified_at']);}
    private function executePointDisbursements(array $point,string $userName,?array $selectedNumbers=null):array
    {
        require_once __DIR__.'/../decaissement/model/FicheDecaissement.php';$model=new FicheDecaissement($this->pdo);$errors=[];$processed=[];$processedTotal=0.0;$selected=$selectedNumbers===null?null:array_fill_keys($selectedNumbers,true);
        $progressDone=0;$progressTotal=count(array_filter((array)($point['items']??[]),static fn($item)=>$selected===null||isset($selected[(string)$item['fiche_number']])));foreach((array)($point['items']??[]) as $item){$num=(string)$item['fiche_number'];if($selected!==null&&!isset($selected[$num]))continue;FinancialWorkflowProgress::step('Traitement des fiches du point journalier.',$progressDone++,$progressTotal);$current=$model->getByNum($num);if(!$current){$errors[]=$num.' : fiche indisponible';continue;}if(!empty($current['decaisse']))continue;try{DailyPointPaymentPolicy::assertPayment($this->pdo,$current,(float)$item['amount']);SupplierPaymentGuard::assertFiche($this->pdo,$current);}catch(Throwable $e){$errors[]=$num.' : '.$e->getMessage();continue;}$this->pdo->prepare('UPDATE fiche_decaissement SET conforme=1,approuve=1,etat_fiche=0,date_valid=COALESCE(date_valid,NOW()),updated_at=NOW() WHERE num_fiche=:n AND decaisse=0')->execute(['n'=>$num]);$current=$model->getByNum($num);$amount=(float)$item['amount'];$total=(float)$current['montant_fiche'];$ok=false;$error='';try{if($amount+0.01<$total){$result=$model->decaisserPartiel($num,$amount,(string)($item['next_disbursement_date']??''),$userName,$_SERVER['REMOTE_ADDR']??'',0);$ok=!empty($result['ok']);$error=(string)($result['error']??'échec');}else{$ok=$model->decaisserCompta($num,$userName,$_SERVER['REMOTE_ADDR']??'',0,true);$error='fiche non prête au décaissement';}}catch(Throwable $e){$error=$e->getMessage();}$after=$model->getByNum($num);if(!$ok&&!empty($after['decaisse'])&&abs((float)$after['montant_fiche']-$amount)<0.001)$ok=true;if(!$ok)$errors[]=$num.' : '.$error;if($ok){$processed[]=$num;$processedTotal+=$amount;}}
        FinancialWorkflowProgress::step('Traitement des fiches du point terminé.',$progressTotal,$progressTotal);
        return['numbers'=>$processed,'total'=>$processedTotal,'errors'=>$errors];
    }
    public function items(int $id):array{$s=$this->pdo->prepare('SELECT * FROM daily_disbursement_point_items WHERE point_id=:id ORDER BY id');$s->execute(['id'=>$id]);return$s->fetchAll(PDO::FETCH_ASSOC)?:[];}
    public function signatures(int $id):array{$s=$this->pdo->prepare('SELECT * FROM daily_disbursement_point_signatures WHERE point_id=:id ORDER BY signed_at');$s->execute(['id'=>$id]);return$s->fetchAll(PDO::FETCH_ASSOC)?:[];}
    public function payments(int $id):array{$s=$this->pdo->prepare('SELECT p.*,GROUP_CONCAT(i.fiche_number ORDER BY i.id SEPARATOR ", ") fiche_numbers FROM daily_disbursement_point_payments p LEFT JOIN daily_disbursement_point_payment_items i ON i.payment_id=p.id WHERE p.point_id=:id GROUP BY p.id ORDER BY p.paid_at');$s->execute(['id'=>$id]);return$s->fetchAll(PDO::FETCH_ASSOC)?:[];}
    public function profileSignature(int $userId):string{$s=$this->pdo->prepare('SELECT signature,signature_data FROM user_devis_banamur WHERE id=:id LIMIT 1');$s->execute(['id'=>$userId]);$row=$s->fetch(PDO::FETCH_ASSOC)?:[];$path=trim((string)($row['signature']??''));if($path==='')return'';$root=realpath(dirname(__DIR__));$resolved=$root?realpath($root.'/'.ltrim($path,'/')):false;if($resolved&&$root&&str_starts_with($resolved,$root.'/uploads/user_signatures/')&&is_file($resolved)&&is_readable($resolved)){if(trim((string)($row['signature_data']??''))===''){$binary=@file_get_contents($resolved);if(is_string($binary)&&@getimagesizefromstring($binary)!==false){$data='data:image/png;base64,'.base64_encode($binary);$this->pdo->prepare('UPDATE user_devis_banamur SET signature_data=:data WHERE id=:id')->execute(['data'=>$data,'id'=>$userId]);}}return$path;}return trim((string)($row['signature_data']??''))!==''?$path:'';}
    public function profileSignatureData(int $userId):string{$s=$this->pdo->prepare('SELECT signature_data FROM user_devis_banamur WHERE id=:id LIMIT 1');$s->execute(['id'=>$userId]);return trim((string)$s->fetchColumn());}
    public function emailEnabled(int $userId):bool{$s=$this->pdo->prepare('SELECT email_enabled FROM daily_disbursement_point_preferences WHERE user_id=:u');$s->execute(['u'=>$userId]);$v=$s->fetchColumn();return$v===false?true:(bool)$v;}
