    public function visibleHistory(int $userId,bool $financeOrAdmin):array{if($financeOrAdmin)return$this->pdo->query('SELECT * FROM daily_disbursement_points ORDER BY point_date DESC,version_no DESC LIMIT 500')->fetchAll(PDO::FETCH_ASSOC)?:[];$s=$this->pdo->prepare('SELECT DISTINCT p.* FROM daily_disbursement_points p WHERE EXISTS(SELECT 1 FROM daily_disbursement_point_authorizations a WHERE a.point_id=p.id AND a.user_id=:u) OR EXISTS(SELECT 1 FROM daily_disbursement_point_signatures s WHERE s.point_id=p.id AND s.user_id=:u2) ORDER BY p.point_date DESC,p.version_no DESC LIMIT 200');$s->execute(['u'=>$userId,'u2'=>$userId]);return$s->fetchAll(PDO::FETCH_ASSOC)?:[];}
    public function reconcileAlreadyDisbursedPoint(int $pointId,string $userName):void
    {
        $check=$this->pdo->prepare("SELECT p.status,COUNT(i.id) item_count,SUM(CASE WHEN COALESCE(f.decaisse,0)=0 THEN 1 ELSE 0 END) unpaid_count,MAX(f.date_decaisse) last_paid_at FROM daily_disbursement_points p LEFT JOIN daily_disbursement_point_items i ON i.point_id=p.id LEFT JOIN fiche_decaissement f ON CONVERT(f.num_fiche USING utf8mb4) COLLATE utf8mb4_general_ci=CONVERT(i.fiche_number USING utf8mb4) COLLATE utf8mb4_general_ci WHERE p.id=:id GROUP BY p.id,p.status");$check->execute(['id'=>$pointId]);$row=$check->fetch(PDO::FETCH_ASSOC);if(!$row||(string)$row['status']!=='certified')throw new RuntimeException('Ce point ne peut pas être rapproché.');if((int)$row['item_count']<=0||(int)$row['unpaid_count']>0)throw new RuntimeException('Ce point contient encore une fiche réellement à payer.');
        $update=$this->pdo->prepare("UPDATE daily_disbursement_points SET status='paid',paid_at=COALESCE(:paid_at,NOW()),paid_by_name=:name WHERE id=:id AND status='certified'");$update->execute(['paid_at'=>$row['last_paid_at']?:null,'name'=>'Rapproché par '.$userName.' · décaissement antérieur déjà enregistré','id'=>$pointId]);try{require_once __DIR__.'/DailyPointExternalSignatureService.php';(new DailyPointExternalSignatureService($this->pdo))->revokePaymentKeys($pointId);}catch(Throwable $e){}
    }
    public function synchronizeFullyPaidPoints():array
    {
        $ids=$this->pdo->query("SELECT p.id FROM daily_disbursement_points p WHERE p.status='certified' AND p.certified_at IS NOT NULL AND EXISTS(SELECT 1 FROM daily_disbursement_point_signatures sig WHERE sig.point_id=p.id AND sig.role_code='dg' AND COALESCE(sig.signature_path,'')<>'') AND EXISTS(SELECT 1 FROM daily_disbursement_point_items i WHERE i.point_id=p.id) AND NOT EXISTS(SELECT 1 FROM daily_disbursement_point_items i LEFT JOIN fiche_decaissement f ON CONVERT(f.num_fiche USING utf8mb4) COLLATE utf8mb4_general_ci=CONVERT(i.fiche_number USING utf8mb4) COLLATE utf8mb4_general_ci WHERE i.point_id=p.id AND (f.num_fiche IS NULL OR COALESCE(f.decaisse,0)<>1 OR ABS(COALESCE(f.montant_fiche,0)-i.amount)>0.001)) ORDER BY p.id")->fetchAll(PDO::FETCH_COLUMN)?:[];
        $ids=array_values(array_unique(array_filter(array_map('intval',$ids),static fn(int $id):bool=>$id>0)));
        if(!$ids)return[];
        $marks=implode(',',array_fill(0,count($ids),'?'));
        $sql="UPDATE daily_disbursement_points p SET p.status='paid',p.paid_at=COALESCE(p.paid_at,(SELECT MAX(f.date_decaisse) FROM daily_disbursement_point_items i JOIN fiche_decaissement f ON CONVERT(f.num_fiche USING utf8mb4) COLLATE utf8mb4_general_ci=CONVERT(i.fiche_number USING utf8mb4) COLLATE utf8mb4_general_ci WHERE i.point_id=p.id),NOW()),p.paid_by_name=COALESCE(NULLIF(p.paid_by_name,''),'Synchronisation automatique · fiches intégralement décaissées') WHERE p.id IN ($marks) AND p.status='certified'";
        $this->pdo->prepare($sql)->execute($ids);
        try{require_once __DIR__.'/DailyPointExternalSignatureService.php';$external=new DailyPointExternalSignatureService($this->pdo);foreach($ids as $id){$external->revokePaymentKeys($id);$external->revokePointLinks($id);}}catch(Throwable $e){}
        try{AuditTrail::log('daily_disbursement_points_auto_archived',['module'=>'decaissement','action'=>'auto_archive_paid_points','entity_type'=>'daily_disbursement_point','result'=>'success','details'=>['point_ids'=>$ids,'reason'=>'all_point_fiches_are_disbursed']],$this->pdo);}catch(Throwable $e){}
        return$ids;
    }
    public function payablePoints():array{$pointId=(int)($_SESSION['daily_point_payment_access']['point_id']??0);if($pointId>0){$s=$this->pdo->prepare("SELECT * FROM daily_disbursement_points WHERE id=:id AND status='certified' AND certified_at IS NOT NULL");$s->execute(['id'=>$pointId]);return$s->fetchAll(PDO::FETCH_ASSOC)?:[];}return$this->pdo->query("SELECT * FROM daily_disbursement_points WHERE status='certified' AND certified_at IS NOT NULL ORDER BY point_date,version_no,id")->fetchAll(PDO::FETCH_ASSOC)?:[];}
    private function notify(int $userId,string $title,string $message,string $link):void{if($userId<=0)return;try{new NotificationManager($this->pdo);$channels=$this->emailEnabled($userId)?['system','email']:['system'];$s=$this->pdo->prepare("INSERT INTO system_notifications(created_at,event_key,sub_key,title,message,link_url,recipient_user_id,channels_json,payload_json) VALUES(NOW(),'daily_disbursement_point','signature',:title,:message,:link,:uid,:channels,'{}')");$s->execute(['title'=>$title,'message'=>$message,'link'=>$link,'uid'=>$userId,'channels'=>json_encode($channels)]);}catch(Throwable $e){}}
    private function ensureSchema():void
    {
        $this->pdo->exec("CREATE TABLE IF NOT EXISTS daily_disbursement_points(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,point_date DATE NOT NULL,version_no INT NOT NULL DEFAULT 1,status VARCHAR(30) NOT NULL DEFAULT 'draft',total_amount DECIMAL(18,2) NOT NULL DEFAULT 0,item_count INT NOT NULL DEFAULT 0,stopped_by_user_id INT NULL,stopped_by_name VARCHAR(190) NULL,stopped_by_signature_path VARCHAR(255) NULL,stopped_at DATETIME NULL,certified_at DATETIME NULL,paid_at DATETIME NULL,paid_by_user_id INT NULL,paid_by_name VARCHAR(190) NULL,paid_by_signature_path VARCHAR(255) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_day_version(point_date,version_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        try{$columns=$this->pdo->query('SHOW COLUMNS FROM daily_disbursement_points')->fetchAll(PDO::FETCH_COLUMN,0)?:[];$alter=[];$definitions=['stopped_by_signature_path'=>'VARCHAR(255) NULL AFTER stopped_by_name','paid_at'=>'DATETIME NULL AFTER certified_at','paid_by_user_id'=>'INT NULL AFTER paid_at','paid_by_name'=>'VARCHAR(190) NULL AFTER paid_by_user_id','paid_by_signature_path'=>'VARCHAR(255) NULL AFTER paid_by_name'];foreach($definitions as $column=>$definition)if(!in_array($column,$columns,true))$alter[]="ADD COLUMN $column $definition";if($alter)$this->pdo->exec('ALTER TABLE daily_disbursement_points '.implode(',',$alter));}catch(Throwable $e){}
        $this->pdo->exec("CREATE TABLE IF NOT EXISTS daily_disbursement_point_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,point_id BIGINT UNSIGNED NOT NULL,fiche_number VARCHAR(120) NOT NULL,amount DECIMAL(18,2) NOT NULL DEFAULT 0,beneficiary VARCHAR(190) NULL,designation VARCHAR(255) NULL,precision_text TEXT NULL,chantier_id INT NULL,chantier_code VARCHAR(80) NULL,chantier_title VARCHAR(190) NULL,snapshot_json LONGTEXT NULL,UNIQUE KEY uq_point_fiche(point_id,fiche_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$this->pdo->exec("CREATE TABLE IF NOT EXISTS daily_disbursement_point_authorizations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,point_id BIGINT UNSIGNED NOT NULL,user_id INT NOT NULL,role_code VARCHAR(30) NOT NULL,delegator_user_id INT NULL,granted_by_user_id INT NULL,granted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,revoked_at DATETIME NULL,UNIQUE KEY uq_point_user(point_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$this->pdo->exec("CREATE TABLE IF NOT EXISTS daily_disbursement_point_signatures(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,point_id BIGINT UNSIGNED NOT NULL,user_id INT NOT NULL,signer_name VARCHAR(190) NOT NULL,role_code VARCHAR(30) NOT NULL,delegator_user_id INT NULL,signature_path VARCHAR(255) NULL,signed_at DATETIME NOT NULL,ip_address VARCHAR(64) NULL,UNIQUE KEY uq_point_signer(point_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        $this->pdo->exec("CREATE TABLE IF NOT EXISTS daily_disbursement_point_payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,point_id BIGINT UNSIGNED NOT NULL,user_id INT NOT NULL,payer_name VARCHAR(190) NOT NULL,signature_path VARCHAR(255) NULL,payment_mode VARCHAR(40) NOT NULL,payment_reference VARCHAR(190) NULL,proof_path VARCHAR(255) NULL,total_amount DECIMAL(18,2) NOT NULL DEFAULT 0,item_count INT NOT NULL DEFAULT 0,paid_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_point_payments(point_id,paid_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        $this->pdo->exec("CREATE TABLE IF NOT EXISTS daily_disbursement_point_payment_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_id BIGINT UNSIGNED NOT NULL,point_item_id BIGINT UNSIGNED NOT NULL,fiche_number VARCHAR(120) NOT NULL,amount DECIMAL(18,2) NOT NULL DEFAULT 0,UNIQUE KEY uq_payment_point_item(payment_id,point_item_id),KEY idx_payment_fiche(fiche_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        $this->pdo->exec("CREATE TABLE IF NOT EXISTS daily_disbursement_point_reviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,point_id BIGINT UNSIGNED NOT NULL,point_item_id BIGINT UNSIGNED NOT NULL,fiche_number VARCHAR(120) NOT NULL,decision VARCHAR(20) NOT NULL,old_amount DECIMAL(18,2) NOT NULL,new_amount DECIMAL(18,2) NULL,next_date DATE NULL,reason VARCHAR(1000) NOT NULL,reviewed_by_user_id INT NOT NULL,reviewed_by_name VARCHAR(190) NOT NULL,snapshot_json LONGTEXT NULL,reviewed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_point_reviews(point_id,reviewed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    }
